	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		StorageLocation
	 */
		public StorageLocation createStorageLocation( CreateStorageLocationCommand command ) {

		StorageLocation entity = new StorageLocation();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setStorageLocationId( command.getStorageLocationId() );
            entity.setCode( command.getCode() );
            entity.setTemperatureControlled( command.getTemperatureControlled() );
            entity.setCapacity( command.getCapacity() );
            entity.setCapacityUnit( command.getCapacityUnit() );
            entity.setLocationType( command.getLocationType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of StorageLocation {0} ", entity.toString() );

		return entity;
	}

