            entity.setCode( command.getCode() );
            entity.setTemperatureControlled( command.getTemperatureControlled() );
            entity.setCapacity( command.getCapacity() );
            entity.setCapacityUnit( command.getCapacityUnit() );
            entity.setWarehouse( command.getWarehouse() );
            entity.setParentLocation( command.getParentLocation() );
            entity.setChildLocations( command.getChildLocations() );
            entity.setInventoryItems( command.getInventoryItems() );
            entity.setLocationType( command.getLocationType() );

		// ------------------------------------------
